let tab='market',renderers=[],modalRenderers=[],listObserver,listScope,routeVersion=0,jobs=[],serverOffset=0,editor=null,toastTimer,stateLoading=false,dirty=false,saveBusy=false,lastSavedTemplate=null,studioArchive=false;
function toast(message){const t=$('#toast');t.textContent=message;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.hidden=true,5000)}
function guard(next='?tab='+tab){if(boot.allowed)return true;location.href=boot.user?'/account/?'+new URLSearchParams({err:boot.guest_message}):'/login/?'+new URLSearchParams({next:'/ycards/'+next});return false}
async function api(path,data,options={}){const res=await fetch('/ycards/api/'+path,{signal:options.signal,method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json','X-YCards-CSRF':boot.csrf},body:data===undefined?undefined:JSON.stringify(data)});let value;try{value=await res.json()}catch(error){if(error.name==='AbortError')throw error;throw Error('服务器响应异常，请稍后重试')}if(!res.ok){if(value.redirect)location.href=value.redirect;throw Error(value.error||'请求失败')}return value}
function listen(root,event,selector,fn){root.addEventListener(event,e=>{const el=e.target.closest(selector);if(el&&root.contains(el))Promise.resolve(fn(e,el)).catch(err=>toast(err.message))})}
function title(eyebrow,heading,desc,extra=''){return `<div class="page-title"><div><p class="eyebrow">${eyebrow}</p><h1>${heading}</h1><p class="muted">${desc}</p></div>${extra}</div>`}
