async function route(next,params={},push=true){if(saveBusy){toast('正在保存，请稍候');return}if(dirty&&!confirm('尚有未保存的设计，离开编辑器？'))return;if(!['market','auction'].includes(next)&&!guard('?tab='+next))return;dirty=false;cleanup();tab=next;const ver=++routeVersion;history[push?'pushState':'replaceState']({},'', '/ycards/?'+new URLSearchParams({tab:next,...params}));$$('#navigation a').forEach(a=>a.classList.toggle('active',a.dataset.tab===tab));main.innerHTML='<div class="empty">正在加载…</div>';try{if(next==='market'||next==='mine')await listPage(next,ver);else if(next==='create')await creation(ver);else if(next==='production')await production(params.tid);else if(next==='auction')await auctions.page();else if(next==='auction-history')await auctions.page(true);else if(next==='history')await historyPage();else await listPage('market',ver)}catch(err){if(ver===routeVersion)main.innerHTML=`<div class="empty error">${esc(err.message)}<p><button id="retry-page">重试</button></p></div>`}}
listen(document,'click','a[data-tab],#history-link,#auction-history-link,#task-progress',async(e,a)=>{e.preventDefault();await route(a.dataset.tab||new URL(a.href).searchParams.get('tab'))});
listen(main,'click','#retry-page',()=>route(tab));
