 card.name=name;for(const host of $$(`.preview[data-id="${card.id}"]`)){const title=host.closest('.tile')?.querySelector('h3');if(title)title.textContent=name;host.setAttribute('aria-label','查看 '+name);const select=host.closest('.tile')?.querySelector('[data-select-card]');if(select)select.setAttribute('aria-label','选择 '+name)}
