function blank(){return {format_version:2,thickness_mm:.76,corner_radius_mm:3.18,name:'未命名卡片',material:'plastic',orientation:'portrait',width_mm:53.98,height_mm:85.60,corners:'round',color:'color',layers:[]}}
function cost(d){let a=100n,n=1n,den=1n;if(d.material==='glass')n*=2n;if(d.color==='mono'){n*=3n;den*=4n}for(const l of d.layers){const masks=BigInt(Number(!!l.mask)+Number(!!l.repeat_mask));if(l.type==='image')a+=BigInt(l.position==='front'?200:l.position==='behind'?150:0);else if(l.type==='foil')a+=300n+200n*masks+BigInt(l.position==='front'?100:0);else if(l.type==='glow')a+=200n+200n*masks+BigInt(l.position==='front'?50:0);else{if(l.effect==='vinyl')n*=2n;else{n*=3n;den*=2n}n*=5n**masks;den*=4n**masks}}return (a*n+den-1n)/den}
function options(values,selected){return Object.entries(values).map(([k,v])=>`<option value="${k}" ${selected===k?'selected':''}>${v}</option>`).join('')}
