function repeatDefaults(){return {kind:'text',text:'YCARDS',pattern:null,font:'sans',size_mm:6,pattern_width_mm:12,spacing_mm:3,density:6,angle:-25,x:0,y:0}}
function upgradeDesign(d){d.format_version=2;d.thickness_mm=.76;d.corner_radius_mm=3.18;for(const l of d.layers){if(l.type==='foil'&&['text','pattern'].includes(l.effect)){l.repeat_mask={...repeatDefaults(),kind:l.pattern?'pattern':'text',pattern:l.pattern,text:l.text||'YCARDS',density:l.density||6,angle:l.angle??-25,size_mm:d.height_mm/(l.density||6)*.55};l.effect='color'}if(l.type==='glow'&&l.effect==='circle')l.effect='ring';if(l.type==='glow')Object.assign(l,{glow_width:l.glow_width??4,feather:l.feather??.65,opacity:l.opacity??1,tint:l.tint||'#bdeaff'});if(l.effect==='lenticular')Object.assign(l,{pitch_mm:l.pitch_mm??.7,strength:l.strength??.65})}return d}
