async function importImage(file,mask){if(file.size>4*1024*1024)throw Error('请选择小于 4 MB 的资源');const svg=file.type==='image/svg+xml'||file.name.toLowerCase().endsWith('.svg');if(svg&&!mask)throw Error('图片图层仅支持 PNG');let src;
 if(svg){let text=await file.text();if(/<!|url\s*\(|(?:https?|data|javascript):/i.test(text))throw Error('SVG 不允许外部资源或声明');const doc=new DOMParser().parseFromString(text,'image/svg+xml');const allowed=new Set(['svg','g','path','rect','circle','ellipse','line','polyline','polygon']);const attrs=new Set(['xmlns','width','height','viewBox','x','y','x1','x2','y1','y2','cx','cy','r','rx','ry','d','points','transform','fill','stroke','stroke-width','fill-rule','stroke-linecap','stroke-linejoin','opacity','fill-opacity','stroke-opacity','preserveAspectRatio']);const nodes=[...doc.querySelectorAll('*')];if(nodes.length>2000||nodes.some(n=>!allowed.has(n.localName)||[...n.attributes].some(a=>!attrs.has(a.name))))throw Error('SVG 只支持基础矢量图形，禁止脚本、样式和引用');doc.documentElement.setAttribute('xmlns','http://www.w3.org/2000/svg');if(!doc.documentElement.hasAttribute('width'))doc.documentElement.setAttribute('width','1024');if(!doc.documentElement.hasAttribute('height'))doc.documentElement.setAttribute('height','1024');text=new XMLSerializer().serializeToString(doc);src='data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(text)));
 }else{const bytes=new Uint8Array(await file.arrayBuffer());if(bytes.length<8||[137,80,78,71,13,10,26,10].some((n,i)=>n!==bytes[i]))throw Error('请选择有效 PNG 图片');src=await new Promise((resolve,reject)=>{const f=new FileReader();f.onload=()=>resolve(f.result);f.onerror=reject;f.readAsDataURL(file)})}
 if(mask)return ycBinaryMask(src);
 const im=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('PNG 无法读取'));i.src=src});if(im.width>2048||im.height>2048){const c=document.createElement('canvas'),s=2048/Math.max(im.width,im.height);c.width=Math.round(im.width*s);c.height=Math.round(im.height*s);c.getContext('2d').drawImage(im,0,0,c.width,c.height);src=c.toDataURL('image/png');toast('大图已在本机缩小至 2048 像素')}return src
}
async function addLayer(type){if(editor.design.layers.filter(l=>l.type===type).length>=64){toast('此类图层已达 64 层上限');return}let image=null;if(type==='image'){const f=document.createElement('input');f.type='file';f.accept='image/png';f.onchange=async()=>{if(f.files[0])try{image=await importImage(f.files[0],false);insert()}catch(e){toast(e.message)}};f.click()}else insert();
 function insert(){if(!editor)return;const d=editor.design,l={id:crypto.randomUUID(),type,effect:Object.keys(effects[type])[0],side:Math.abs(editor.renderer.ry)>90&&d.material==='glass'?'back':'front',position:'surface',distance_mm:0,x:0,y:0,width:d.width_mm,height:d.height_mm,rotation:0,scope:'full',mask:null,image,repeat_mask:null,glow_width:4,feather:.65,opacity:1,tint:'#bdeaff',pitch_mm:.7,strength:.65};d.layers.push(l);editor.selected=l.id;dirty=true;updateEditor()}
}
async function saveEditor(formal){
 if(!editor||saveBusy)return;const editing=editor;let tid;
 if(formal){tid=prompt('正式模板 TID（1～12 位英文字母或数字，区分大小写）',editing.pendingSave?.tid||'');if(tid===null)return;if(!/^[a-zA-Z0-9]{1,12}$/.test(tid)){toast('TID 格式不正确');return}if(!confirm('设计保存后不可再次编辑，名称可随时修改，是否继续？'))return}
 const pending=editing.pendingSave;if(!pending||pending.version!==editing.localVersion||pending.tid!==tid||pending.formal!==formal)editing.pendingSave={key:crypto.randomUUID(),version:editing.localVersion,tid,formal};
 const key=editing.pendingSave.key,payload={design:editing.design,draft_id:editing.draft_id,revision:editing.revision,tid,confirmed:formal,request_key:key};
 const controls=$$('button,input,select',main).map(el=>[el,el.disabled]);controls.forEach(([el])=>el.disabled=true);saveBusy=true;
 editing.renderer.suspended=true;cancelAnimationFrame(editing.renderer.frame);editing.renderer.frame=null;
 let phase='准备保存…';const started=Date.now(),progress=()=>{const el=$('#save-progress');if(el)el.textContent=phase+` · ${Math.floor((Date.now()-started)/1000)} 秒`},timer=setInterval(progress,1000);progress();
 try{
  let saved;
  try{saved=await saveYCardsDesign({path:formal?'templates':'drafts',payload,csrf:boot.csrf,onProgress:text=>{phase=text;progress()}})}
  catch(error){phase='正在核对保存结果…';progress();const status=await api('save-status/'+key).catch(()=>null);if(status?.saved)saved=status.result;else throw error}
  dirty=false;editing.pendingSave=null;saveBusy=false;
  if(formal){lastSavedTemplate={tid:saved.tid,design:editing.design};studioArchive=false;toast('正式模板已保存，可去生产');await route('create')}
  else{editing.draft_id=saved.draft_id;editing.revision=saved.revision;phase='草稿已保存';progress();toast('草稿已保存')}
 }catch(e){phase=e.message+'；可重试保存';progress();toast(phase)}
 finally{clearInterval(timer);saveBusy=false;controls.forEach(([el,disabled])=>el.disabled=disabled);if(!editing.renderer.disposed){editing.renderer.suspended=false;editing.renderer.schedule()}}
}
async function production(tid){await refreshState();main.innerHTML=title('PRODUCTION','让设计成为收藏','个人逐张制作，或用 4×4 工厂版面生产。')+'<div id="jobs"></div><button class="fab" id="choose-production" aria-label="选择模板生产">+</button>';renderJobs();$('#choose-production').onclick=()=>productionDialog();if(tid)await productionDialog(tid)}
function renderJobs(){const el=$('#jobs');if(!el)return;el.innerHTML=jobs.length?jobs.map(j=>`<article class="status-job"><div class="row spread"><div><h3>${esc(j.tid)} · ${j.mode==='personal'?'个人生产':'工厂生产'}</h3><span class="muted">${j.count} ${j.mode==='personal'?'张':'版'} · 实付 ${fmt(j.total)} YIDT${j.coupon?` · ${esc(j.coupon.code)} 减免 ${fmt(j.coupon.discount)} YIDT`:''}${j.improvement?` · 改善投入 ${fmt(j.improvement)} YIDT`:''}</span></div><span>${j.state==='done'?'已完成':'生产中'}</span></div><progress max="1" value="${jobProgress(j)}"></progress><div class="row spread"><span class="helper">${j.state==='done'?`理论产量 ${j.count*(j.mode==='personal'?1:16)} 张 · 入库 ${j.sheets.reduce((n,s)=>n+(s.result?.product_count||0),0)} 个成品`:`剩余 ${Math.max(0,Math.ceil(j.ends-(Date.now()/1000+serverOffset)))} 秒`}</span><a href="?tab=mine" data-tab="mine">查看仓库 →</a></div><details><summary>逐版进度与结果</summary><div class="sheet-list">${j.sheets.map(s=>`<div class="sheet-row"><span>第 ${s.ordinal} ${j.mode==='personal'?'张':'版'} · 生产编号 ${s.production_number}<br>成熟度 ${s.maturity} · ${fmt(s.cost)} YIDT</span><span>${s.result?s.result.destroyed?'玻璃损毁 · 不入库':`${s.result.product_count} 个成品 · 损耗编号 ${s.result.defect_number}`:'等待完成'}</span></div>`).join('')}</div></details></article>`).join(''):'<div class="empty"><strong>第一张成品，从这里诞生</strong>点击 + 选择自己的正式模板。</div>'}
function jobProgress(j){return Math.max(0,Math.min(1,(Date.now()/1000+serverOffset-j.started)/(j.ends-j.started||1)))}
async function productionDialog(tid){const {items}=await api('templates?summary=1&production=1'),templates=items.filter(t=>t.tid&&!t.archived);if(!templates.length){toast('请先保存正式模板，或在创作中恢复已归档模板');return}if(tid&&!templates.some(t=>t.tid===tid)){toast('该模板已归档或不可用，请先在创作中查看');return}dialog(`<h2>创建生产批次</h2><div class="panel"><label>正式模板<select id="produce-tid">${templates.map(t=>`<option value="${esc(t.tid)}" ${t.tid===tid?'selected':''}>${esc(t.name)} · ${esc(t.tid)}</option>`).join('')}</select></label><div class="form-grid"><label>生产方式<select id="produce-mode"><option value="personal">个人 · 每次一张</option><option value="factory">工厂 · 每版 16 张</option></select></label><label>版数<input id="produce-count" type="number" min="1" max="100" value="1" disabled></label></div><label>改善投入 YIDT（每增加 1000，全部损耗概率减半）<input id="produce-improvement" type="number" min="0" max="100000" step="1000" value="0" disabled></label><label>优惠码（可选）<input id="produce-coupon" maxlength="40" autocomplete="off" placeholder="键入优惠码"></label><p class="helper" id="production-risk"></p><button id="get-quote">计算报价</button></div><div id="quote-result"></div>`);let quote=null,key=crypto.randomUUID();const params=()=>({tid:$('#produce-tid').value,mode:$('#produce-mode').value,count:Number($('#produce-count').value),improvement:Number($('#produce-improvement').value),coupon:$('#produce-coupon').value.trim()});
 const invalidate=()=>{quote=null;$('#quote-result').innerHTML='';const factory=$('#produce-mode').value==='factory';$('#produce-count').disabled=!factory;$('#produce-improvement').disabled=!factory;if(!factory){$('#produce-count').value=1;$('#produce-improvement').value=0}const t=templates.find(t=>t.tid===params().tid);$('#production-risk').textContent=t.material==='glass'?(factory?'玻璃每版基础损毁概率 50%，改善投入可降低全部损耗。':'玻璃每张 25% 概率损毁；损毁不退款，仍计入成熟度及理论产量。'):(factory?'工厂基础损耗：每层漏印 2%、歪印 1%；每次漏裁 2%、裁歪 1%。':'塑料个人生产不应用工厂缺陷。')};$$('input,select',modalBody).forEach(e=>e.oninput=invalidate);invalidate();
 $('#get-quote').onclick=async()=>{try{const p=params();quote=await api('quote',p);if(!$('#quote-result'))return;$('#quote-result').innerHTML=`<div class="sheet-list"><table class="quote-table"><tr><th>版／张</th><th>成熟度</th><th>费用 YIDT</th><th>秒</th></tr>${quote.sheets.map((s,i)=>`<tr><td>${i+1}</td><td>${s.maturity}</td><td>${fmt(s.cost)}</td><td>${s.seconds}</td></tr>`).join('')}</table></div><div class="panel"><h3>合计 ${fmt(quote.total)} YIDT</h3>${quote.coupon?`<p class="helper">原价 ${fmt(quote.original_total)} YIDT · 优惠 ${fmt(quote.discount)} YIDT · 优惠码 ${esc(quote.coupon.code)}<br>优惠不改变生产时间或损耗概率。</p>`:''}<p class="muted">总时间 ${quote.seconds.toFixed(2)} 秒 · 改善投入 ${fmt(quote.improvement)} YIDT<br>生产将在服务端继续，关闭页面不影响计时。</p><button id="start-production" class="primary">支付并开始生产</button></div>`;$('#start-production').onclick=async()=>{const btn=$('#start-production');btn.disabled=true;try{await api('produce',{...p,quote_token:quote.token,request_key:key});closeModal();toast('生产任务已创建');await route('production')}catch(e){toast(e.message);btn.disabled=false}}}catch(e){toast(e.message)}}
}
async function historyPage(){const data=await api('history');main.innerHTML=title('TRANSACTIONS','历史交易','管理当前挂售，查看每次卡片流转。')+'<div class="history-tabs"></div><div id="history-rows"></div>';const names={active:'当前挂售',bought:'买入记录',sold:'卖出记录',withdrawn:'已下架记录'};let selected='active';function render(){ $('.history-tabs').innerHTML=Object.entries(names).map(([k,v])=>`<button data-history="${k}" class="${k===selected?'active':''}">${v} · ${data[k].length}</button>`).join('');$('#history-rows').innerHTML=data[selected].length?data[selected].map(r=>`<div class="history-row"><div><strong>${esc(r.name)}</strong><div class="cid">${esc(r.cid)}</div></div><div>${money(r.price_cents)} YIDT${selected==='sold'?person(r.buyer_profile,'买家'):selected==='bought'?person(r.seller_profile,'卖家'):''}${selected==='bought'?`<div class="helper">手续费 ${money(r.fee_cents)} YIDT</div>`:''}</div><div class="helper">${new Date((r.updated||r.created)*1000).toLocaleString()}${(r.yidt_receipts||[]).map(receipt=>`<p><a target="_blank" rel="noopener" href="https://yidt.yitiao.org/explorer/tx/${receipt.hash}">${esc(receipt.label)}</a></p>`).join('')}</div>${selected==='active'?`<div class="row"><input aria-label="新售价" id="price-${r.id}" type="number" step="0.01" min="0.01" value="${r.price_cents/100}"><button data-reprice="${r.id}">改价</button><button data-withdraw="${r.id}">下架</button></div>`:''}</div>`).join(''):'<div class="empty">暂无记录</div>'}$('.history-tabs').onclick=e=>{if(e.target.dataset.history){selected=e.target.dataset.history;render()}};$('#history-rows').onclick=async e=>{const id=e.target.dataset.reprice||e.target.dataset.withdraw;if(!id)return;try{if(e.target.dataset.withdraw&&!confirm('确认下架这张卡片？'))return;await api('listing',{listing_id:id,action:e.target.dataset.withdraw?'withdraw':'reprice',price:$('#price-'+id).value});toast(e.target.dataset.withdraw?'已下架':'售价已更新');await historyPage()}catch(err){toast(err.message)}};render()}
async function refreshState(){if(!boot.allowed||stateLoading)return;stateLoading=true;try{const s=await api('state');jobs=s.jobs;serverOffset=s.now-Date.now()/1000;$('#balance').innerHTML=`${s.yidt_balance==null?'绑定 YIDT 钱包以继续':esc(s.yidt_balance)+' <small>YIDT</small>'}`;$('#balance').title=`可用积分；拍卖冻结 ${money(s.auction_held_cents||0)} YIDT`;$('#auction-held').hidden=!s.auction_held_cents;$('#auction-held').textContent=`冻结 ${money(s.auction_held_cents||0)} YIDT`;const active=jobs.find(j=>j.state==='active'),el=$('#task-progress');el.hidden=!active;if(active)el.textContent=`生产 ${Math.floor(jobProgress(active)*100)}% · ${Math.max(0,Math.ceil(active.ends-s.now))}s`;if(tab==='production'){const oldOpen=$$('details[open]',$('#jobs')||main).map(e=>[...e.parentElement.parentElement.children].indexOf(e.parentElement));renderJobs();oldOpen.forEach(i=>{const x=$$('#jobs details')[i];if(x)x.open=true})}}finally{stateLoading=false}}
